import React from "react";
import { motion } from "framer-motion";
import { TESTIMONIALS } from "../types";
import { Quote, MapPin, Star } from "lucide-react";

export default function Testimonials() {
  return (
    <section id="reviews" className="py-24 lg:py-32 bg-white">
      <div className="container mx-auto px-6">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <motion.div className="flex items-center justify-center gap-4 mb-6">
            <div className="h-px w-12 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="text-sm font-semibold tracking-[0.15em] uppercase text-amber-500">Testimonials</span>
            <div className="h-px w-12 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900" style={{ fontFamily: "Georgia, serif" }}>
            What our clients <span className="text-amber-500">say</span>
          </h2>
        </motion.div>

        {/* Grid */}
        <div className="grid md:grid-cols-2 gap-8">
          {TESTIMONIALS.map((testimonial, i) => (
            <motion.div
              key={testimonial.name}
              className="bg-gradient-to-br from-gray-50 to-white rounded-3xl p-8 shadow-lg shadow-gray-100 relative"
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1, duration: 0.5 }}
              whileHover={{ y: -6, boxShadow: "0 25px 50px rgba(0,0,0,0.1)" }}
            >
              {/* Quote Icon */}
              <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center mb-6">
                <Quote size={28} className="text-amber-600" />
              </div>

              {/* Stars */}
              <div className="flex gap-1 mb-4">
                {[...Array(5)].map((_, j) => (
                  <Star key={j} size={16} className="text-amber-400 fill-amber-400" />
                ))}
              </div>

              {/* Quote */}
              <p className="text-lg text-gray-700 mb-6 italic leading-relaxed">
                &ldquo;{testimonial.quote}&rdquo;
              </p>

              {/* Author */}
              <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                <div>
                  <h4 className="font-semibold text-gray-900">{testimonial.name}</h4>
                  <p className="text-sm text-gray-500">{testimonial.role}</p>
                </div>
                <div className="flex items-center gap-2 text-sm text-gray-500">
                  <MapPin size={14} />
                  <span>{testimonial.city}</span>
                </div>
              </div>

              {/* Accent */}
              <div className="absolute top-8 right-8 w-20 h-20 bg-amber-400/5 rounded-full -z-10" />
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
